const ListPurchaseIDsForTenantDesc = `-- name: ListPurchaseIDsForTenantDesc :many
SELECT p.id,
    p.purchased_at
FROM purchases p
WHERE p.tenant_id = $1
    AND (
        $2::uuid IS NULL
        OR EXISTS (
            SELECT 1
            FROM episodes e
            WHERE e.tenant_id = p.tenant_id
                AND e.id = p.episode_id
                AND e.series_id = $2::uuid
        )
        OR EXISTS (
            SELECT 1
            FROM volumes v
            WHERE v.tenant_id = p.tenant_id
                AND v.id = p.volume_id
                AND v.series_id = $2::uuid
        )
        OR EXISTS (
            SELECT 1
            FROM series_bundles b
            WHERE b.tenant_id = p.tenant_id
                AND b.id = p.series_bundle_id
                AND b.series_id = $2::uuid
        )
    )
    AND (
        $3::uuid IS NULL
        OR p.episode_id = $3::uuid
    )
    AND (
        $4::uuid IS NULL
        OR p.user_id = $4::uuid
    )
    AND (
        $5::text IS NULL
        OR EXISTS (
            SELECT 1
            FROM users u
            WHERE u.tenant_id = p.tenant_id
                AND u.id = p.user_id
                AND lower(u.email) = lower($5::text)
        )
    )
    AND (
        $6::timestamptz IS NULL
        OR p.purchased_at >= $6::timestamptz
    )
    AND (
        $7::timestamptz IS NULL
        OR p.purchased_at < $7::timestamptz
    )
    AND (
        $8::uuid IS NULL
        OR (
            $9::boolean
            AND (p.purchased_at, p.id) <= ($10::timestamptz, $8::uuid)
        )
        OR (
            NOT $9::boolean
            AND (p.purchased_at, p.id) < ($10::timestamptz, $8::uuid)
        )
    )
ORDER BY p.purchased_at DESC,
    p.id DESC
LIMIT $11
`

