const ReplaceUnappliedRefund = `-- name: ReplaceUnappliedRefund :exec
UPDATE unapplied_refunds
SET refunded_amount = $1::integer,
    currency = $2::text,
    received_at = NOW()
WHERE tenant_id = $3
    AND provider = $4::text
    AND provider_payment_id = $5::text
`

type ReplaceUnappliedRefundParams struct {
	RefundedAmount    int32     `json:"refunded_amount"`
	Currency          string    `json:"currency"`
	TenantID          uuid.UUID `json:"tenant_id"`
	Provider          string    `json:"provider"`
	ProviderPaymentID string    `json:"provider_payment_id"`
}

// Sets a held refund to the total that stays refunded once one of the refunds
// it counted has failed, the one place a held amount goes down. Nothing is
// held for the payment in the ordinary case, and nothing changes then.
func (q *Queries) ReplaceUnappliedRefund(ctx context.Context, arg ReplaceUnappliedRefundParams) error {
	_, err := q.db.ExecContext(ctx, ReplaceUnappliedRefund,
		arg.RefundedAmount,
		arg.Currency,
		arg.TenantID,
		arg.Provider,
		arg.ProviderPaymentID,
	)
	return err
}

const RequestStaffRefundInPart = `-- name: RequestStaffRefundInPart :one
UPDATE purchases
SET staff_refund_requested_total = COALESCE(refunded_amount, 0) + $1::integer
WHERE tenant_id = $2
    AND id = $3
    AND staff_refund_requested_total IS NULL
    AND revocation_reason IS NULL
    AND refunded_at IS NULL
    AND COALESCE(refunded_amount, 0) + $1::integer < price_at_purchase
RETURNING staff_refund_attempt
`

type RequestStaffRefundInPartParams struct {
	Amount   int32     `json:"amount"`
	TenantID uuid.UUID `json:"tenant_id"`
	ID       uuid.UUID `json:"id"`
}

// Marks a refund in part of amount as asked of the provider, before it is
// asked, recording the refunded total it brings the purchase to, and answers
// the attempt the request belongs to. The purchase keeps opening its episode.
// It answers no row when there is nothing for this call to mark: a refund in
// part is waiting already, which a second request racing the first finds once
// that one commits, something revoked the purchase, or the amount no longer
// leaves part of the price unrefunded.
func (q *Queries) RequestStaffRefundInPart(ctx context.Context, arg RequestStaffRefundInPartParams) (int32, error) {
	row := q.db.QueryRowContext(ctx, RequestStaffRefundInPart, arg.Amount, arg.TenantID, arg.ID)
	var staff_refund_attempt int32
	err := row.Scan(&staff_refund_attempt)
	return staff_refund_attempt, err
}

const RevokePurchaseForStaff = `-- name: RevokePurchaseForStaff :one
UPDATE purchases
SET revoked_at = COALESCE(revoked_at, NOW()),
    revocation_reason = 'staff'
WHERE tenant_id = $1
    AND id = $2
    AND revocation_reason IS DISTINCT FROM 'staff'
    AND revocation_reason IS DISTINCT FROM 'dispute'
    AND staff_refund_requested_total IS NULL
RETURNING id
`

type RevokePurchaseForStaffParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	ID       uuid.UUID `json:"id"`
}

// Revokes a purchase staff are about to refund, before the provider is asked,
// so that whatever the provider reports about the refund lands on a purchase
// already revoked. It answers no row when there is nothing for this call to
// change: staff revoked it already, which a second request racing the first
// finds once that one commits, the reader's dispute revoked it first, which
// the dispute keeps, or a refund in part staff asked for is waiting for the
// provider, whose idempotency key this refund would be sent under. A refund
// recorded first gives way to staff while its instant stays.
func (q *Queries) RevokePurchaseForStaff(ctx context.Context, arg RevokePurchaseForStaffParams) (uuid.UUID, error) {
	row := q.db.QueryRowContext(ctx, RevokePurchaseForStaff, arg.TenantID, arg.ID)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const TenantHasPurchases = `-- name: TenantHasPurchases :one
SELECT EXISTS (
        SELECT 1
        FROM purchases
        WHERE tenant_id = $1
    )
`

// Whether the tenant has any purchase, from a provider's checkout or a store,
// test ones included, which keeps the tenant currency from changing.
func (q *Queries) TenantHasPurchases(ctx context.Context, tenantID uuid.UUID) (bool, error) {
	row := q.db.QueryRowContext(ctx, TenantHasPurchases, tenantID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const UpsertTenantPaymentConfig = `-- name: UpsertTenantPaymentConfig :one
INSERT INTO tenant_payment_config (
        tenant_id,
        provider,
        enabled,
        credentials_encrypted,
        credential_hints,
        currency,
        updated_at
    )
VALUES ($1, $2, $3, $4, $5, $6, NOW()) ON CONFLICT (tenant_id) DO
UPDATE
SET provider = EXCLUDED.provider,
    enabled = EXCLUDED.enabled,
    credentials_encrypted = EXCLUDED.credentials_encrypted,
    credential_hints = EXCLUDED.credential_hints,
    currency = EXCLUDED.currency,
    updated_at = NOW()
RETURNING tenant_id, provider, enabled, created_at, updated_at, credentials_encrypted, credential_hints, currency
`

type UpsertTenantPaymentConfigParams struct {
	TenantID             uuid.UUID       `json:"tenant_id"`
	Provider             string          `json:"provider"`
	Enabled              bool            `json:"enabled"`
	CredentialsEncrypted json.RawMessage `json:"credentials_encrypted"`
	CredentialHints      json.RawMessage `json:"credential_hints"`
	Currency             string          `json:"currency"`
}

func (q *Queries) UpsertTenantPaymentConfig(ctx context.Context, arg UpsertTenantPaymentConfigParams) (TenantPaymentConfig, error) {
	row := q.db.QueryRowContext(ctx, UpsertTenantPaymentConfig,
		arg.TenantID,
		arg.Provider,
		arg.Enabled,
		arg.CredentialsEncrypted,
		arg.CredentialHints,
		arg.Currency,
	)
	var i TenantPaymentConfig
	err := row.Scan(
		&i.TenantID,
		&i.Provider,
		&i.Enabled,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CredentialsEncrypted,
		&i.CredentialHints,
		&i.Currency,
	)
	return i, err
}
